/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing
/// Data contract class for customer payment proposal batch job <c>METAMEXCustPaymeProposalService</c>
/// </summary>
[DataContractAttribute]
class METAMEXCustStmtSendContract
{
    private JournalId               journalId;
    private FromDate                fromDate;
    private ToDate                  toDate;

}

Method.Source:
public JournalId parmJournalNum(JournalId _journalId = journalId)
{
    journalId = _journalId;
    return journalId;
}

public FromDate parmFromDate(FromDate _fromdate = fromdate)
{
    fromDate = _fromdate;
    return fromDate;
}

public ToDate parmToDate(ToDate _todate = todate)
{
    toDate = _todate;
    return toDate;
}
